import{_ as t,c as i,o as a,ag as o}from"./chunks/framework.B3RpK1bM.js";const h=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/contributing.md","filePath":"en_EN/contributing.md","lastUpdated":1769658044000}'),n={name:"en_EN/contributing.md"};function r(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><p>Contributing to the project is not an easy task, but we have organized different levels of work content to encourage everyone&#39;s participation.</p><h2 id="simple-tasks" tabindex="-1">Simple Tasks <a class="header-anchor" href="#simple-tasks" aria-label="Permalink to &quot;Simple Tasks&quot;">​</a></h2><ol><li>Read the instructions and wiki documentation, correct any errors in the document and areas you find unclear, and submit them as Pull Requests.</li><li>Create tutorials, introductions, shows, or help others in your field of interest. If it&#39;s public, please submit them to <code>cryingnights7v@gmail.com</code>.</li><li>Try running your first ezgal framework project during the process. Feel free to provide feedback on issues if there are any problems encountered.</li></ol><h2 id="medium-tasks" tabindex="-1">Medium Tasks <a class="header-anchor" href="#medium-tasks" aria-label="Permalink to &quot;Medium Tasks&quot;">​</a></h2><ol><li>Participate in discussions related to the grammar design of ezgal interpreter, share unique insights from your perspective.</li><li>Attempt to fix existing issues, such as those reported in issues, create your own Pull Requests.</li><li>Share games developed using ezgal, showcasing outstanding works through our channels. We welcome all kinds of excellent projects that can be showcased.</li></ol><h2 id="advanced-tasks" tabindex="-1">Advanced Tasks <a class="header-anchor" href="#advanced-tasks" aria-label="Permalink to &quot;Advanced Tasks&quot;">​</a></h2><ol><li>Participate in the development of the ezgal game framework ecosystem.</li><li>Contact us at <code>cryingnights7v@gmail.com</code>, participate in the maintenance of security-related work for the project.</li><li>Try making ezgal better by participating in editor development related work.</li><li>Participate in our milestone planning.</li></ol><h1 id="tag-explanation" tabindex="-1">Tag Explanation <a class="header-anchor" href="#tag-explanation" aria-label="Permalink to &quot;Tag Explanation&quot;">​</a></h1><p>We defined four groups of tags based on requirements:</p><ul><li>fix: Project needs correction</li><li>new: New features added to the project</li><li>bug: Errors found in the project</li><li>cve: Incorrect severity level</li></ul><p>Three groups were also defined based on system definition:</p><ul><li>os: Android</li><li>os: Linux</li><li>os: Windows</li></ul><p>We defined three categories based on project type:</p><ul><li>CI/CD: Issues originating from control flow</li><li>Ezgal: Issues originating from the framework itself</li><li>Ezlang: Issues originating from the interpreter</li></ul><p>This makes it easier for people to filter their tasks when discussing and contributing.</p>',17)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
